import axios from 'axios';

export const SERVER_BASE_URL = process.env.REACT_APP_SERVER_URL || 'http://localhost:8082';
const API_BASE_URL = process.env.REACT_APP_API_URL || `${SERVER_BASE_URL}/api`;

const api = axios.create({
    baseURL: API_BASE_URL,
});

// Add request interceptor to include auth token
api.interceptors.request.use((config) => {
    const token = localStorage.getItem('token');
    const userId = localStorage.getItem('userId');
    if (token) {
        config.headers.Authorization = `Bearer ${token}`;
    } else {
        // Use basic authentication for development
        config.headers.Authorization = `Basic ${btoa('admin:admin')}`;
    }
    if (userId) {
        config.headers['User-Id'] = userId;
    }
    return config;
});

export const ticketApi = {
    // Create a new ticket
    createTicket: async (ticketData, attachments) => {
        const formData = new FormData();

        // Add ticket data
        Object.keys(ticketData).forEach(key => {
            if (ticketData[key] !== null && ticketData[key] !== undefined) {
                formData.append(key, ticketData[key]);
            }
        });

        // Add attachments
        if (attachments && attachments.length > 0) {
            attachments.forEach((file, index) => {
                formData.append('attachments', file);
            });
        }

        const response = await api.post('/tickets', formData, {
            headers: {
                'Content-Type': 'multipart/form-data',
            },
        });
        return response.data;
    },

    // Get all tickets (admin)
    getAllTickets: async () => {
        const response = await api.get('/tickets');
        return response.data;
    },

    // Get user's tickets
    getMyTickets: async () => {
        const response = await api.get('/tickets/my');
        return response.data;
    },

    // Get ticket by ID
    getTicketById: async (id) => {
        const response = await api.get(`/tickets/${id}`);
        return response.data;
    },

    // Update ticket status
    updateTicketStatus: async (id, status) => {
        const response = await api.put(`/tickets/${id}/status`, null, {
            params: { status }
        });
        return response.data;
    },

    // Assign ticket to user
    assignTicket: async (id, assignedToId) => {
        const response = await api.put(`/tickets/${id}/assign`, null, {
            params: { assignedToId }
        });
        return response.data;
    },

    // Delete ticket
    deleteTicket: async (id) => {
        await api.delete(`/tickets/${id}`);
    },

    getUsers: async () => {
        const response = await api.get('/users');
        return response.data;
    },
};

export const commentApi = {
    // Add comment to ticket
    addComment: async (commentData) => {
        const response = await api.post('/comments', commentData);
        return response.data;
    },

    // Get comments for a ticket
    getCommentsByTicket: async (ticketId) => {
        const response = await api.get(`/comments/ticket/${ticketId}`);
        return response.data;
    },

    // Update comment
    updateComment: async (id, content) => {
        const response = await api.put(`/comments/${id}`, null, {
            params: { content }
        });
        return response.data;
    },

    // Delete comment
    deleteComment: async (id) => {
        await api.delete(`/comments/${id}`);
    },
};

export default api;
